// Curated, source-only audit decisions. This does not edit application files.
const fs = require("node:fs");
const path = require("node:path");
const index = require("./source-index.json");
const base = "artifacts/clinicflow/src/";
const findings = [];
function finding(id, group, roles, page, state, file, needle, action, replacement, reason, evidence = "S: source branch and render sink traced") {
  const source = file.startsWith("artifacts/") || file.startsWith("lib/") && file.startsWith("lib/public-pages") ? file : base + file;
  const text = fs.readFileSync(source, "utf8");
  const pos = text.indexOf(needle);
  if (pos < 0) throw new Error(`${id}: source quote not found in ${source}: ${needle}`);
  const line = text.slice(0, pos).split("\n").length;
  findings.push({id, group, roles, page, state, current: needle, source: `${source}:${line}`, action, replacement, reason, evidence});
}
const F = finding;
